class Solution
{
    Node* first = nullptr;
    Node* previous = nullptr;
    void inorder(Node* node)
    {
        if (!node) return;
        inorder(node->left);
        if (!previous)
        {
            first = node;
        } else
        {
            previous->right = node;
            node->left = previous;
        }
        previous = node;
        inorder(node->right);
    }
public:
    Node* treeToDoublyList(Node* root)
    {
        first = nullptr;
        previous = nullptr;
        if (!root) return nullptr;
        inorder(root);
        first->left = previous;
        previous->right = first;
        return first;
    }
};
